Definition shz (Mx : mem) (g0 : Z) : Prop := forall j, 0 <= j < 4 -> L5.u8_at RSEGS Mx (F / 8 + 2147450880 + g0 + j) 0.
Lemma shz_mk (Mx : mem) g0 c : c = 2147450880 + g0 ->
