(* [comment removed for export] *)
Definition keptS (lo nw : Z) (Wx : Z -> Prop) (Ma Mb : mem) : Prop :=
  (forall a, spc <= a < sp -> ~ (spc + lo <= a < spc + lo + nw) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, F / 8 + 2147450880 <= a < F / 8 + 2147450880 + 64 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, F + 32 <= a < F + 480 -> ~ Wx a -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)).
Lemma keptS_binl lo nw (Wx : Z -> Prop) (Ma Mb : mem) y fby (len : nat) w0 w1 : keptS lo nw Wx Ma Mb ->
  F + 32 <= y -> y + 32 <= F + 480 -> (forall a, y <= a < y + 32 -> ~ Wx a) -> 0 <= y -> y + 32 <= 2 ^ 64 ->
