Definition sregs7 (Ri : bvmap 5 word) : Prop :=
  getr Ri (reg 2) = Z_to_bv 64 spc /\ getr Ri (reg 3) = getr R (reg 3) /\ getr Ri (reg 4) = getr R (reg 4) /\ getr Ri (reg 8) = Z_to_bv 64 sp /\ getr Ri (reg 9) = Z_to_bv 64 spc
  /\ getr Ri (reg 18) = Z_to_bv 64 (F / 8 + SBL) /\ getr Ri (reg 19) = Z_to_bv 64 F /\ getr Ri (reg 26) = Z_to_bv 64 F /\ getr Ri (reg 27) = Z_to_bv 64 SBL.
