Lemma MSCALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 (ko g0 : Z) M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 -> ko = 8 * g0 -> (ko = 224 \/ ko = 288 \/ ko = 352) ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + ko + 8) -> getr R3 (reg 11) = Z_to_bv 64 0 -> getr R3 (reg 12) = Z_to_bv 64 24 ->
  shz M3 g0 ->
  (forall R4 (M4 : mem) model4,
      GM [D1] BX1 M4 model4 LK3 Aw1 cr1 -> regs_preserved R3 R4 -> PM.zeros_at M4 (F + ko + 8) 24 ->
      (forall a, F + ko <= a < F + ko + 8 -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a)) -> kept (fun a => F + ko + 8 <= a < F + ko + 32) M3 M4 ->
      L5SAR.ek L ar (BX1 ++ LBX) FF sp SCR [] M3 M4 ->   (* [comment removed for export] *)
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R4 ra M4 model4) K) ->
