(* [comment removed for export] *)
Lemma WTCALL D1 (INC1 : incl D D1) Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) (bx ex : bool) :
  GM [D1] BX0 M3 model3 LK3 Aw1 cr1 ->
  enc_atA M3 ov osk en -> sink_atA M3 osk k -> ec_stateA M3 oec bx cat -> PMSTA.base_okA RSEGS AD M3 -> PQSTA.err_okA RSEGS AD AAD AQ M3 ex ->
  PMSP.credit_le (NESKA.spa_pot P (NESK.sk_c k)) cr1 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 ov ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 Aw4 (k' : NESK.sink) cr4,
      GM [D1] (NECS.eown en k') M4 model4 LK4 Aw4 cr4 -> regs_preserved R3 R4 ->
      enc_atA M4 ov osk en -> sink_atA M4 osk k' -> ec_stateA M4 oec bx cat -> PMSTA.base_okA RSEGS AD M4 -> PQSTA.err_okA RSEGS AD AAD AQ M4 ex ->
      NESK.sk_z k + 6 <= NESK.sk_z k' <= NESK.sk_z k + 15 ->
      PMSP.credit_keep cr1 cr4 (NESKA.spa_pot P (NESK.sk_c k)) (NESKA.spa_pot P (NESK.sk_c k')) ->
      kept (L5.in_rng (osk, 24)) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 WTSPC M3 model3) K.
Proof.
