Lemma keep_all7 D1 (LBf : list (Z * Z)) (FFx : list fframe) LKx crx Awx (Ma Mb : mem) {Mh : mem} Vx (en1 : enc) (k1 : NESK.sink) bx ex :
  ri_inv (HIk D1) LBf FFx LKx crx Awx Mh Vx -> (forall f, In f FF -> In f FFx) -> L5SAR.ek L ar LBf FF sp SCR [] Ma Mb ->
  incl (enc_own en1) LBf -> incl (NESK.sink_own k1) LBf ->
  enc_atA Ma ov osk en1 -> sink_atA Ma osk k1 -> ec_stateA Ma oec bx cat -> PMSTA.base_okA RSEGS AD Ma -> PQSTA.err_okA RSEGS AD AAD AQ Ma ex ->
