Lemma DIVCALL D1 (INC1 : incl D D1) Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (fbx x0 x1 : Z) :
  GM [D1] BX0 M3 model3 LK3 Aw1 cr1 -> PMSTA.base_okA RSEGS AD M3 ->
  getr R3 (reg 1) = Z_to_bv 64 RA_DIV -> REG0 R3 ->
  getr R3 (reg 10) = Z_to_bv 64 XO -> getr R3 (reg 11) = Z_to_bv 64 (spc + 24) -> getr R3 (reg 12) = Z_to_bv 64 QO -> getr R3 (reg 13) = Z_to_bv 64 RO ->
  getr R3 (reg 14) = Z_to_bv 64 1 ->
  PQATSS.binl_at RSEGS M3 XO fbx (PQATSS.wlen x0 x1) x0 x1 -> 1 <= x0 + 2 ^ 64 * x1 -> shz M3 28 ->
  L5.u8_at RSEGS M3 QO 0 -> PM.zeros_at M3 (QO + 8) 24 -> shz M3 36 ->
  L5.u8_at RSEGS M3 RO 0 -> PM.zeros_at M3 (RO + 8) 24 -> shz M3 44 ->
  L5.u8_at RSEGS M3 (spc + 24) 0 -> L5.u64_at RSEGS M3 (spc + 32) 1 -> L5.u64_at RSEGS M3 (spc + 40) NETSA.TEN9 -> L5.u64_at RSEGS M3 (spc + 48) 0 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 (fbq fbr : Z) (lq : nat) (q0 q1 : Z) (lr : nat) (r0 : Z),
      GM [D1] BX0 M4 model4 LK4 Aw1 cr1 -> regs_preserved R3 R4 -> PMSTA.base_okA RSEGS AD M4 ->
      PQATSS.binl_at RSEGS M4 QO fbq lq q0 q1 -> (lq <= 2)%nat -> Z.testbit fbq 0 = false ->
      PQATSS.binl_at RSEGS M4 RO fbr lr r0 0 -> (lr <= 1)%nat -> Z.testbit fbr 0 = false ->
      kept (fun a => (QO <= a < QO + 32) \/ (RO <= a < RO + 32)) M3 M4 ->
      L5SAR.ek L ar (BX0 ++ LBX) FF sp SCR [] M3 M4 ->   (* [comment removed for export] *)
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 RA_DIV M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 DIVPC M3 model3) K.
