Lemma TOBCALL Aw1 M3 model3 LK3 (fx3 : FPState) R3 (bx ex : bool) :
  GM [D] BX0 M3 model3 LK3 Aw1 cr ->
  enc_atA M3 ov osk en -> sink_atA M3 osk k -> ec_stateA M3 oec bx cat -> PMSTA.base_okA RSEGS AD M3 -> PQSTA.err_okA RSEGS AD AAD AQ M3 ex ->
  getr R3 (reg 1) = Z_to_bv 64 RA_TOB -> REG0 R3 ->
  getr R3 (reg 10) = Z_to_bv 64 d -> getr R3 (reg 11) = Z_to_bv 64 n -> getr R3 (reg 12) = Z_to_bv 64 XO ->
  L5.u8_at RSEGS M3 XO 0 -> PM.zeros_at M3 (XO + 8) 24 -> shz M3 28 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 Aw4 cr4 (rc : Z) (D4 : list (list Z)),
      GM [D4] BX0 M4 model4 LK4 Aw4 cr4 -> incl D D4 -> regs_preserved R3 R4 ->
      getr R4 (reg 11) = Z_to_bv 64 rc ->
      ((rc = 0 /\ exists fbx x0 x1, PQATSS.binl_at RSEGS M4 XO fbx (PQATSS.wlen x0 x1) x0 x1 /\ Z.testbit fbx 0 = false)
       \/ (rc = 22 /\ PQATSS.binl_at RSEGS M4 XO 0 0%nat 0 0)) ->
      enc_atA M4 ov osk en -> sink_atA M4 osk k -> ec_stateA M4 oec bx cat -> PMSTA.base_okA RSEGS AD M4 -> PQSTA.err_okA RSEGS AD AAD AQ M4 ex ->
      PMSP.credit_keep cr cr4 (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D r RC)) (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D4 r RC)) ->
      kept (fun a => XO <= a < XO + 32) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 RA_TOB M4 model4) K) ->
