Lemma JZSTAGE D1 (INC1 : incl D D1) M6 model6 LK6 Aw6 cr6 (fx6 : FPState) R6 (k' : NESK.sink) (b' e' : bool) (fbx : Z) :
  GM [D1] (NECS.eown en k') M6 model6 LK6 Aw6 cr6 ->
  enc_atA M6 ov osk en -> sink_atA M6 osk k' -> ec_stateA M6 oec b' cat -> PMSTA.base_okA RSEGS AD M6 -> PQSTA.err_okA RSEGS AD AAD AQ M6 e' ->
  (b = true -> b' = true) -> (e = true -> e' = true) -> NESK.sk_z k <= NESK.sk_z k' <= NESK.sk_z k + 15 ->
  PMSP.credit_keep cr cr6 (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D r RC)) (PM.credit_add (NECSA.pot_encA L ar P en k') (TSPE7 D1 r RC)) ->
  sregs7 R6 -> getr R6 (reg 20) = Z_to_bv 64 ov -> getr R6 (reg 21) = Z_to_bv 64 XO -> getr R6 (reg 22) = Z_to_bv 64 oec -> getr R6 (reg 23) = Z_to_bv 64 p ->
  L5.u8_at RSEGS M6 XO fbx -> 0 <= fbx < 256 -> Z.testbit fbx 0 = false ->
