Lemma WT_THEN_J D1 (INC1 : incl D D1) Aw1 cr1 M5 model5 LK5 (fx5 : FPState) R5 (b5 e5 : bool) (fbx fq fr : Z) :
  GM [D1] BX0 M5 model5 LK5 Aw1 cr1 ->
  enc_atA M5 ov osk en -> sink_atA M5 osk k -> ec_stateA M5 oec b5 cat -> PMSTA.base_okA RSEGS AD M5 -> PQSTA.err_okA RSEGS AD AAD AQ M5 e5 ->
  (b = true -> b5 = true) -> (e = true -> e5 = true) ->
  PMSP.credit_keep cr cr1 (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D r RC)) (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D1 r RC)) ->
  getr R5 (reg 1) = Z_to_bv 64 RA_WT -> sregs7 R5 -> getr R5 (reg 10) = Z_to_bv 64 ov ->
  getr R5 (reg 20) = Z_to_bv 64 ov -> getr R5 (reg 21) = Z_to_bv 64 XO -> getr R5 (reg 22) = Z_to_bv 64 QO -> getr R5 (reg 23) = Z_to_bv 64 RO ->
  getr R5 (reg 24) = Z_to_bv 64 (F + 360) -> getr R5 (reg 25) = Z_to_bv 64 (F + 296) ->
  L5.u8_at RSEGS M5 XO fbx -> 0 <= fbx < 256 -> Z.testbit fbx 0 = false ->
  L5.u8_at RSEGS M5 QO fq -> 0 <= fq < 256 -> Z.testbit fq 0 = false ->
  L5.u8_at RSEGS M5 RO fr -> 0 <= fr < 256 -> Z.testbit fr 0 = false ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 WTSPC M5 model5) K.
Proof.
