Local Ltac wgo CONC KSL fxa Ra MVa TAILa mv :=
  pose proof (LF2CBN( CONC fxa Ra MVa mv )) as PW; feedP PW;
  destruct PW as (fx6 & R6 & M6v & MG6 & _ & FRZ6 & MS6 & KS6 & E1 & E10 & _);
  apply (TAILa fx6 R6 M6v KSL MS6 MG6 FRZ6 KS6 ltac:(vm_compute; reflexivity) E1 E10).
(* [comment removed for export] *)
Lemma WSTAGE D1 (INC1 : incl D D1) Aw1 cr1 M5 model5 LK5 (fx5 : FPState) R5 (b5 e5 : bool) (fbx fbq fbr : Z) (lq : nat) (q0 q1 : Z) (lr : nat) (r0 : Z) :
  GM [D1] BX0 M5 model5 LK5 Aw1 cr1 ->
  enc_atA M5 ov osk en -> sink_atA M5 osk k -> ec_stateA M5 oec b5 cat -> PMSTA.base_okA RSEGS AD M5 -> PQSTA.err_okA RSEGS AD AAD AQ M5 e5 ->
  (b = true -> b5 = true) -> (e = true -> e5 = true) ->
  PMSP.credit_keep cr cr1 (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D r RC)) (PM.credit_add (NECSA.pot_encA L ar P en k) (TSPE7 D1 r RC)) ->
  sregs7 R5 -> getr R5 (reg 20) = Z_to_bv 64 ov -> getr R5 (reg 21) = Z_to_bv 64 XO -> getr R5 (reg 22) = Z_to_bv 64 QO -> getr R5 (reg 23) = Z_to_bv 64 RO ->
  getr R5 (reg 24) = Z_to_bv 64 (F + 360) -> getr R5 (reg 25) = Z_to_bv 64 (F + 296) ->
  L5.u8_at RSEGS M5 XO fbx -> 0 <= fbx < 256 -> Z.testbit fbx 0 = false ->
  PQATSS.binl_at RSEGS M5 QO fbq lq q0 q1 -> (lq <= 2)%nat -> Z.testbit fbq 0 = false ->
  PQATSS.binl_at RSEGS M5 RO fbr lr r0 0 -> (lr <= 1)%nat -> Z.testbit fbr 0 = false ->
  shz M5 36 -> shz M5 44 -> L5.u8_at RSEGS M5 (spc + 24) 0 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 RA_DIV M5 model5) K.
