  getr R5 (reg 10) = Z_to_bv 64 XO -> getr R5 (reg 11) = Z_to_bv 64 (spc + 24) -> getr R5 (reg 12) = Z_to_bv 64 QO -> getr R5 (reg 13) = Z_to_bv 64 RO -> getr R5 (reg 14) = Z_to_bv 64 1 ->
