Local Ltac dfacts D1 INC1 LM :=
  destruct sp_facts as (SP1 & SP2 & SP3 & Hr1 & Hr2 & V2L); assert (HC0 : 0 <= cls <= 16) by (destruct Hcls; lia);
  destruct (GX PQAKR3F.g_ctx) as (SLO & SHI & SPT & A16 & C0);
