  destruct (F_facts D1 INC1 _ _ _ _ _ _ LM) as (HF & F32 & FBIG & DF & FS1 & FS2 & HFL & FFL);
  assert (HV2 : 140735332487296 <= V2 <= 140737488355328) by (clear - V2L SP2 HC0; Lia.lia);
  assert (ALF : PNAENSTP1.aligned F 32) by exact F32; assert (AL2 : PNAENSTP1.aligned V2 32) by exact V32;
  destruct eobj_facts as ((O1 & O2 & O3 & O4) & (K1 & K2 & K3 & K4) & (C1 & C2 & C3 & C4));
  destruct view_pf as (Hp1 & Hp2 & Hp3 & _);
  assert (Hov0 : 0 <= ov < 2 ^ 64) by (clear - O1 O3; Lia.lia); assert (Hoec0 : 0 <= oec < 2 ^ 64) by (clear - C1 C3; Lia.lia); assert (Hp0 : 0 <= p < 2 ^ 64) by (clear - Hp1 Hp3; Lia.lia);
