(* [comment removed for export] *)
Lemma TZCALL D1 (INC1 : incl D D1) Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (ra fbx x0 x1 : Z) :
  GM [D1] BX0 M3 model3 LK3 Aw1 cr1 -> PMSTA.base_okA RSEGS AD M3 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 XO -> getr R3 (reg 11) = Z_to_bv 64 0 ->
  PQATSS.binl_at RSEGS M3 XO fbx (PQATSS.wlen x0 x1) x0 x1 -> shz M3 28 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM [D1] BX0 M4 model4 LK4 Aw1 cr1 -> regs_preserved R3 R4 ->
      getr R4 (reg 10) = Z_to_bv 64 (if Nat.eqb (PQATSS.wlen x0 x1) 0%nat then 0 else 1) ->
      kept (fun _ => False) M3 M4 -> L5SAR.ek L ar (BX0 ++ LBX) FF sp SCR [] M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
